from pathlib import Path
import pcbnew as p,json,hashlib,time
R=Path('/tmp/v7-c124-d-plus-connector-gnd');Q=R/'filled/pcb/maru60.kicad_pcb';H=lambda q:hashlib.sha256(q.read_bytes()).hexdigest();before=H(Q);b=p.LoadBoard(str(Q));assert p.Version()=='9.0.2';ct=json.loads((R/'BUILD_CONTRACT.json').read_text());idx={q.m_Uuid.AsString():q for q in b.GetTracks()};v=idx[ct['new_via']['uuid']];assert isinstance(v,p.PCB_VIA);assert v.GetNetname()=='GND'and v.GetNetCode()==ct['actual_source_GND_net_code'];assert (v.GetPosition().x,v.GetPosition().y)==(17200000,9900000);assert v.GetWidth()==500000 and v.GetDrillValue()==250000 and v.GetViaType()==p.VIATYPE_THROUGH
inv={'tracks':sum(not isinstance(q,p.PCB_VIA)for q in idx.values()),'vias':sum(isinstance(q,p.PCB_VIA)for q in idx.values()),'footprints':len(b.GetFootprints()),'track_length_mm':sum(q.GetLength()/1e6 for q in idx.values()if not isinstance(q,p.PCB_VIA)),'native_version':p.GetBuildVersion()};assert inv['tracks']==9750 and inv['vias']==919 and inv['footprints']==383
(R/'qa/prefill-native-inventory.json').write_text(json.dumps(inv,indent=2)+'\n');start=time.monotonic();b.BuildConnectivity();p.ZONE_FILLER(b).Fill(b.Zones());p.SaveBoard(str(Q),b);r={'prefill_sha256':before,'filled_sha256':H(Q),'seconds':time.monotonic()-start,'zones':len(b.Zones()),'inventory':inv,'status':'UNSELECTED normal-filled combined candidate'};(R/'qa/native-fill.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r,indent=2),flush=True)
